def handle(app, svc):
    resp = svc.apply(app)
    decision = resp.get("decision")
    limit = int(resp.get("limit", 0) or 0)

    if decision == "decline":
        return {"action": "decline", "limit": 0}

    # Network referral rule: self_employed with requested_limit > 6000
    # must go to manual review unless already declined.
    if app.get("employment") == "self_employed" and int(app.get("requested_limit", 0) or 0) > 6000:
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}

    if decision == "refer":
        return {"action": "queue_review", "limit": 0}

    # Fallback: treat undecided as review rather than declining.
    return {"action": "queue_review", "limit": 0}

